import { Command, CommandProposal, CommandResult } from '../contracts';
import { LoopController } from './LoopController';
import { useAppStore } from '../stores/useAppStore';

export class CommandGateway {
  private controller: LoopController;

  constructor(controller: LoopController) {
    this.controller = controller;
  }

  /**
   * Proposals generated by React views, keyboard listeners, or gesture web workers
   * are translated here into fully-formed Commands and dispatched to the loop controller.
   */
  public async propose(proposal: CommandProposal): Promise<CommandResult> {
    const quantizeMode = useAppStore.getState().settings.quantize;
    
    // Generate a unique command identifier
    const commandId = this.generateId();

    const command: Command = {
      id: commandId,
      kind: proposal.kind,
      origin: proposal.origin,
      requestedAtMs: Date.now(),
      quantize: quantizeMode,
      payload: proposal.payload
    };

    // Log the intent proposal for auditing (observability compliance)
    this.logProposal(command);

    try {
      const result = await this.controller.execute(command);
      this.logResult(command, result);
      return result;
    } catch (error) {
      const errorMsg = error instanceof Error ? error.message : String(error);
      useAppStore.getState().setError(`Command failed: ${errorMsg}`);
      return {
        commandId,
        status: 'rejected',
        reason: 'internal-error'
      };
    }
  }

  private generateId(): string {
    if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
      return crypto.randomUUID();
    }
    // Safe fallback for testing and non-secure context runtimes
    return `cmd-${Date.now()}-${Math.random().toString(36).substring(2, 11)}`;
  }

  private logProposal(command: Command): void {
    // Audit log as specified in "Command lifecycle"
    console.debug(`[CommandGateway] Proposing intent:`, {
      id: command.id,
      kind: command.kind,
      origin: command.origin,
      quantize: command.quantize
    });
  }

  private logResult(command: Command, result: CommandResult): void {
    console.debug(`[CommandGateway] Processed command result:`, {
      id: command.id,
      kind: command.kind,
      status: result.status,
      reason: result.reason,
      targetFrame: result.targetFrame
    });
  }
}
